"""`Pupil R card`: generated by export_nodes.py from face_cards.blend; kept by hand from then on."""

NAME = 'Pupil R card'


def build(lib):
    t = lib.new_material(NAME, props={
            'use_transparency_overlap': False,
            'show_transparent_back': False,
            'use_backface_culling': True,
        })

    t.node('ShaderNodeOutputMaterial', 'Material Output', props={
        'location': (600.0, 0.0),
    })
    t.node('ShaderNodeGroup', 'Group', props={
        'node_tree': lib.group('.pupil sticker'),
        'location': (78.64926, -18.301773),
        'width': 217.3529,
    })
    t.node('ShaderNodeTexImage', 'tex.eye_r', props={
        'location': (-486.20352, 0.0),
        'width': 326.20352,
        'label': 'tex.eye_r',
        'show_texture': True,
    })

    t.link('Group', 'Shader', 'Material Output', 'Surface')
    t.link('tex.eye_r', 'Color', 'Group', 'Color')
    t.link('tex.eye_r', 'Alpha', 'Group', 'Alpha')

    t.driver('nodes["Group"].inputs[3].default_value', 'min(max(-14.0985*d, 0.0), 1.0)', variables=[('d', 'TRANSFORMS', [{'id': 'Face card rig', 'bone_target': 'PupilClip_Top.R', 'transform_type': 'LOC_Y', 'transform_space': 'LOCAL_SPACE', 'rotation_mode': 'AUTO'}])])
    t.driver('nodes["Group"].inputs[2].default_value', 'min(max(14.0985*d, 0.0), 1.0)', variables=[('d', 'TRANSFORMS', [{'id': 'Face card rig', 'bone_target': 'PupilClip_Bottom.R', 'transform_type': 'LOC_Y', 'transform_space': 'LOCAL_SPACE', 'rotation_mode': 'AUTO'}])])
    t.driver('nodes["Group"].inputs[4].default_value', 'r', variables=[('r', 'TRANSFORMS', [{'id': 'Face card rig', 'bone_target': 'PupilClip_Top.R', 'transform_type': 'ROT_Z', 'transform_space': 'LOCAL_SPACE', 'rotation_mode': 'AUTO'}])])
    t.driver('nodes["Group"].inputs[5].default_value', 'r', variables=[('r', 'TRANSFORMS', [{'id': 'Face card rig', 'bone_target': 'PupilClip_Bottom.R', 'transform_type': 'ROT_Z', 'transform_space': 'LOCAL_SPACE', 'rotation_mode': 'AUTO'}])])
    return t
